insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-01', 1, 'Concepto de límite', 'facil', '¿Qué significa que lim(x→2) f(x) = 5?', '[{"id":"A","text":"f(2) = 5 obligatoriamente"},{"id":"B","text":"f(x) se acerca a 5 cuando x se acerca a 2"},{"id":"C","text":"f crece sin límite cerca de 2"},{"id":"D","text":"El límite solo existe si f es continua"}]'::jsonb, 'B', 'El límite describe el comportamiento cercano al punto, no el valor en el punto. f(2) puede diferir o no existir.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-02', 1, 'Indeterminación 0/0', 'facil', 'Al evaluar lim(x→1) (x²−1)/(x−1) por sustitución directa se obtiene:', '[{"id":"A","text":"0"},{"id":"B","text":"2"},{"id":"C","text":"0/0 (indeterminación)"},{"id":"D","text":"∞"}]'::jsonb, 'C', 'Numerador 1−1=0 y denominador 1−1=0: forma 0/0. Factorizando (x−1)(x+1)/(x−1) = x+1 → 2, pero la sustitución directa da 0/0.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-03', 1, 'Límites 0/0', 'facil', 'El valor de lim(x→1) (x²−1)/(x−1) es:', '[{"id":"A","text":"2"},{"id":"B","text":"1"},{"id":"C","text":"0"},{"id":"D","text":"No existe"}]'::jsonb, 'A', 'Simplificando: (x−1)(x+1)/(x−1) = x+1 para x≠1; el límite es 1+1 = 2.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-04', 1, 'Forma ∞/∞', 'facil', 'lim(x→∞) (3x²+2x)/(5x²−1) presenta la forma:', '[{"id":"A","text":"0/0"},{"id":"B","text":"Ninguna indeterminación"},{"id":"C","text":"∞ − ∞"},{"id":"D","text":"∞/∞"}]'::jsonb, 'D', 'Numerador y denominador tienden a ∞: forma ∞/∞. Dividiendo por x²: (3+2/x)/(5−1/x²) → 3/5.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-05', 1, 'Límites ∞/∞', 'media', 'lim(x→∞) (3x²+2x)/(5x²−1) es igual a:', '[{"id":"A","text":"0"},{"id":"B","text":"3/5"},{"id":"C","text":"3/2"},{"id":"D","text":"∞"}]'::jsonb, 'B', 'Mandam los términos de mayor grado: 3x²/5x² = 3/5.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-06', 1, 'Interpretación', 'facil', 'Si lim(x→3⁻) f(x) = 4 y lim(x→3⁺) f(x) = 7, entonces:', '[{"id":"A","text":"El límite bilateral es 4"},{"id":"B","text":"El límite bilateral es 5.5"},{"id":"C","text":"El límite bilateral no existe"},{"id":"D","text":"El límite bilateral es 7"}]'::jsonb, 'C', 'Los límites laterales deben coincidir para que exista el límite bilateral. 4 ≠ 7, luego no existe.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-07', 1, 'Límites 0/0', 'media', 'lim(x→0) (√(x+4) − 2)/x es igual a:', '[{"id":"A","text":"0"},{"id":"B","text":"4"},{"id":"C","text":"1/2"},{"id":"D","text":"1/4"}]'::jsonb, 'D', 'Racionalizando: (x)/(x(√(x+4)+2)) = 1/(√(x+4)+2) → 1/4.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-08', 1, 'Reconocer 0/0', 'facil', '¿Cuál de estas expresiones es de la forma 0/0 cuando x→0?', '[{"id":"A","text":"sin(x)/x"},{"id":"B","text":"(x+1)/x"},{"id":"C","text":"x/(x+1)"},{"id":"D","text":"(eˣ+1)/x"}]'::jsonb, 'A', 'sin(0)=0 y denominador 0: forma 0/0. Su límite notable es 1.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-09', 1, 'Límites infinitos', 'media', 'lim(x→2⁺) 3/(x−2) es igual a:', '[{"id":"A","text":"0"},{"id":"B","text":"+∞"},{"id":"C","text":"3/2"},{"id":"D","text":"−∞"}]'::jsonb, 'B', 'Denominador positivo muy pequeño → cociente positivo muy grande: +∞.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-10', 1, 'Límites 0/0', 'media', 'lim(x→3) (x²−9)/(x−3) es igual a:', '[{"id":"A","text":"0"},{"id":"B","text":"3"},{"id":"C","text":"6"},{"id":"D","text":"9"}]'::jsonb, 'C', '(x−3)(x+3)/(x−3) = x+3 → 6.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n1-11', 1, 'Grados y ∞/∞', 'media', 'lim(x→∞) (2x³−x+1)/(5x²+4) es igual a:', '[{"id":"A","text":"2/5"},{"id":"B","text":"0"},{"id":"C","text":"−∞"},{"id":"D","text":"+∞"}]'::jsonb, 'D', 'El numerador (grado 3) domina al denominador (grado 2): cociente ~ (2/5)x → +∞.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-01', 2, 'Evaluación polar', 'facil', 'Para r = 2 + 2cos(θ), cuando θ = π, r vale:', '[{"id":"A","text":"4"},{"id":"B","text":"2"},{"id":"C","text":"0"},{"id":"D","text":"−2"}]'::jsonb, 'C', 'cos(π) = −1, luego r = 2 + 2(−1) = 0. Es el punto de retroceso de la cardioide.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-02', 2, 'Conversión polar-cartesiana', 'facil', 'El punto polar (r, θ) = (2, π/2) corresponde en cartesianas a:', '[{"id":"A","text":"(0, 2)"},{"id":"B","text":"(2, 0)"},{"id":"C","text":"(−2, 0)"},{"id":"D","text":"(0, −2)"}]'::jsonb, 'A', 'x = r·cos θ = 2·0 = 0; y = r·sin θ = 2·1 = 2.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-03', 2, 'Conversión cartesiana-polar', 'media', 'El punto (1, √3) en polares (r ≥ 0, θ ∈ [0, 2π)) es:', '[{"id":"A","text":"(2, π/6)"},{"id":"B","text":"(√3, π/3)"},{"id":"C","text":"(4, π/3)"},{"id":"D","text":"(2, π/3)"}]'::jsonb, 'D', 'r = √(1+3) = 2; tan θ = √3/1 con x,y > 0 → θ = π/3.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-04', 2, 'Curvas polares', 'facil', 'La ecuación r = 4 representa:', '[{"id":"A","text":"Una recta vertical"},{"id":"B","text":"Una circunferencia centrada en el origen de radio 4"},{"id":"C","text":"Una espiral"},{"id":"D","text":"Una rosa de 4 pétalos"}]'::jsonb, 'B', 'r constante = distancia fija al polo: circunferencia de radio 4.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-05', 2, 'Rosas polares', 'media', '¿Cuántos pétalos tiene la rosa r = 3sin(2θ)?', '[{"id":"A","text":"2"},{"id":"B","text":"3"},{"id":"C","text":"4"},{"id":"D","text":"6"}]'::jsonb, 'C', 'r = a·sin(nθ) con n = 2 par → 2n = 4 pétalos.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-06', 2, 'Evaluación polar', 'media', 'Para r = 1 + cos(θ), el valor máximo de r es:', '[{"id":"A","text":"2"},{"id":"B","text":"1"},{"id":"C","text":"0"},{"id":"D","text":"π"}]'::jsonb, 'A', 'cos θ ≤ 1, máximo en θ = 0: r = 1 + 1 = 2.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-07', 2, 'Simetría polar', 'media', 'La curva r = 2 + 2cos(θ) es simétrica respecto a:', '[{"id":"A","text":"Ningún eje"},{"id":"B","text":"La recta θ = π/2 (eje y)"},{"id":"C","text":"El origen solamente"},{"id":"D","text":"El eje polar (eje x)"}]'::jsonb, 'D', 'cos(−θ) = cos θ, así que r(θ) = r(−θ): simetría respecto al eje polar.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-08', 2, 'Espirales', 'media', 'La gráfica de r = θ para θ ≥ 0 es:', '[{"id":"A","text":"Una circunferencia"},{"id":"B","text":"Una espiral de Arquímedes"},{"id":"C","text":"Una recta por el origen"},{"id":"D","text":"Una cardioide"}]'::jsonb, 'B', 'El radio crece proporcionalmente al ángulo: espiral de Arquímedes.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-09', 2, 'Puntos y trayectorias', 'media', '¿Cuál de estos puntos polares coincide con (2, π/6)?', '[{"id":"A","text":"(2, 13π/6)"},{"id":"B","text":"(−2, π/6)"},{"id":"C","text":"(2, 5π/6)"},{"id":"D","text":"(−2, 13π/6)"}]'::jsonb, 'A', 'Sumar 2π no cambia el punto: π/6 + 2π = 13π/6. La opción con r negativo cambia de cuadrante.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-10', 2, 'Círculos descentrados', 'dificil', 'La ecuación r = 4cos(θ) representa una circunferencia de:', '[{"id":"A","text":"Radio 4 centrada en el origen"},{"id":"B","text":"Radio 2 centrada en (0, 2)"},{"id":"C","text":"Radio 2 centrada en (2, 0)"},{"id":"D","text":"Radio 4 centrada en (4, 0)"}]'::jsonb, 'C', 'Multiplicando por r: r² = 4r·cos θ → x²+y² = 4x → (x−2)²+y² = 4: centro (2,0), radio 2.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n2-11', 2, 'Interpretación', 'dificil', 'Una nave sigue r(θ) = 2 + 2cos(θ). ¿En qué θ la nave pasa por el polo (origen)?', '[{"id":"A","text":"θ = 0"},{"id":"B","text":"θ = π/2"},{"id":"C","text":"Nunca pasa por el origen"},{"id":"D","text":"θ = π"}]'::jsonb, 'D', 'r = 0 ⟺ 2 + 2cos θ = 0 ⟺ cos θ = −1 ⟺ θ = π (mod 2π).', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-01', 3, 'Identificar indeterminación', 'facil', '¿En cuál de estos límites SÍ puede aplicarse directamente L''Hôpital?', '[{"id":"A","text":"lim(x→0) (x+1)/x"},{"id":"B","text":"lim(x→0) (x²+1)/x²"},{"id":"C","text":"lim(x→1) (x+2)/(x−1)"},{"id":"D","text":"lim(x→0) sin(x)/x"}]'::jsonb, 'D', 'Solo sin(x)/x es 0/0 (sin(0)=0). Las demás son de la forma a/0 (a≠0), no indeterminadas: L''Hôpital no aplica directamente.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-02', 3, 'Aplicación directa', 'facil', 'lim(x→0) sin(x)/x usando L''Hôpital es:', '[{"id":"A","text":"0"},{"id":"B","text":"1"},{"id":"C","text":"∞"},{"id":"D","text":"No existe"}]'::jsonb, 'B', 'Derivando numerador y denominador: cos(x)/1 → cos(0) = 1.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-03', 3, 'Derivación correcta', 'media', 'Al aplicar L''Hôpital a lim(x→0) (eˣ−1)/x, el cociente de derivadas es:', '[{"id":"A","text":"eˣ/1"},{"id":"B","text":"(eˣ−1)/1"},{"id":"C","text":"eˣ/x"},{"id":"D","text":"(eˣ−x)/x²"}]'::jsonb, 'A', 'd/dx(eˣ−1) = eˣ; d/dx(x) = 1. El límite es e⁰/1 = 1.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-04', 3, 'Cálculo de límites', 'media', 'lim(x→0) (eˣ−1−x)/x² es igual a:', '[{"id":"A","text":"0"},{"id":"B","text":"1"},{"id":"C","text":"1/2"},{"id":"D","text":"2"}]'::jsonb, 'C', 'Primera aplicación: (eˣ−1)/2x (0/0). Segunda: eˣ/2 → 1/2.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-05', 3, 'Casos no válidos', 'media', '¿Por qué NO puede aplicarse L''Hôpital directamente a lim(x→0⁺) (1/x)?', '[{"id":"A","text":"Porque da +∞"},{"id":"B","text":"Porque x→0⁺ no es un punto válido"},{"id":"C","text":"Porque el denominador es cero"},{"id":"D","text":"Porque no es una indeterminación 0/0 ni ∞/∞"}]'::jsonb, 'D', 'El numerador tiende a 1 (no a 0 ni ∞): es forma 1/0⁺ = +∞, no indeterminada.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-06', 3, 'Cálculo de límites', 'media', 'lim(x→∞) ln(x)/x es igual a:', '[{"id":"A","text":"1"},{"id":"B","text":"0"},{"id":"C","text":"∞"},{"id":"D","text":"−∞"}]'::jsonb, 'B', 'Forma ∞/∞. Derivando: (1/x)/1 = 1/x → 0.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-07', 3, 'Doble aplicación', 'dificil', 'lim(x→0) (1−cos(x))/x² es igual a:', '[{"id":"A","text":"1/2"},{"id":"B","text":"0"},{"id":"C","text":"1"},{"id":"D","text":"2"}]'::jsonb, 'A', 'Primera: sin(x)/2x (0/0). Segunda: cos(x)/2 → 1/2.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-08', 3, 'Cálculo de límites', 'media', 'lim(x→0) tan(x)/x es igual a:', '[{"id":"A","text":"0"},{"id":"B","text":"∞"},{"id":"C","text":"1"},{"id":"D","text":"−1"}]'::jsonb, 'C', 'Derivando: sec²(x)/1 → sec²(0) = 1. También: tan(x) ~ x cerca de 0.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-09', 3, '∞/∞ con exponencial', 'dificil', 'lim(x→∞) x²/eˣ es igual a:', '[{"id":"A","text":"∞"},{"id":"B","text":"0"},{"id":"C","text":"2"},{"id":"D","text":"1"}]'::jsonb, 'B', 'Doble L''Hôpital: 2x/eˣ → 2/eˣ → 0. La exponencial domina a cualquier polinomio.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-10', 3, 'Identificación', 'media', 'lim(x→1) ln(x)/(x−1) es igual a:', '[{"id":"A","text":"0"},{"id":"B","text":"∞"},{"id":"C","text":"e"},{"id":"D","text":"1"}]'::jsonb, 'D', 'Forma 0/0. Derivando: (1/x)/1 → 1/1 = 1.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n3-11', 3, 'Límites notables', 'dificil', 'lim(x→0) (sin(3x))/x es igual a:', '[{"id":"A","text":"3"},{"id":"B","text":"1"},{"id":"C","text":"0"},{"id":"D","text":"1/3"}]'::jsonb, 'A', 'Derivando: 3cos(3x)/1 → 3. Equivale a 3·sin(3x)/(3x) → 3·1.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-01', 4, 'Trayectorias multivariables', 'media', 'Para f(x,y) = x²/(x²+y²), al acercarse a (0,0) por el eje x (y=0, x≠0) el valor es:', '[{"id":"A","text":"1"},{"id":"B","text":"0"},{"id":"C","text":"1/2"},{"id":"D","text":"No está definido en ningún punto del eje"}]'::jsonb, 'A', 'Con y=0: x²/x² = 1 para x≠0. Por el eje y daría 0: el límite no existe.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-02', 4, 'Límite no existe', 'dificil', 'El límite lim((x,y)→(0,0)) x²/(x²+y²):', '[{"id":"A","text":"Es 0"},{"id":"B","text":"Es 1"},{"id":"C","text":"Es 1/2"},{"id":"D","text":"No existe"}]'::jsonb, 'D', 'Por y=0 vale 1 y por x=0 vale 0. Dos trayectorias con distinto límite ⇒ no existe. (No confundir con límites de una variable.)', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-03', 4, 'Trayectorias y=x, y=2x', 'dificil', 'Para f(x,y) = xy/(x²+y²), los límites por y=x y por y=−x valen respectivamente:', '[{"id":"A","text":"0 y 0, luego el límite es 0"},{"id":"B","text":"1/2 y −1/2, luego el límite no existe"},{"id":"C","text":"1 y 1, luego el límite es 1"},{"id":"D","text":"1/2 y 1/2, luego el límite es 1/2"}]'::jsonb, 'B', 'Por y=x: x²/2x² = 1/2. Por y=−x: −x²/2x² = −1/2. Difieren ⇒ no existe.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-04', 4, 'L''Hôpital en cadena', 'dificil', 'Una nave calcula lim(x→0) (e^{2x}−1−2x)/x². El resultado correcto es:', '[{"id":"A","text":"1"},{"id":"B","text":"0"},{"id":"C","text":"2"},{"id":"D","text":"4"}]'::jsonb, 'C', 'Primera: (2e^{2x}−2)/2x. Segunda: 4e^{2x}/2 → 2.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-05', 4, 'Polar vs multivariable', 'dificil', '¿Cuál afirmación es correcta sobre trayectorias polares y límites multivariables?', '[{"id":"A","text":"Un límite multivariable exige el mismo valor por TODAS las trayectorias; una sola discrepancia prueba que no existe"},{"id":"B","text":"Si el límite por toda recta y= mx coincide, el límite multivariable existe seguro"},{"id":"C","text":"Son exactamente lo mismo"},{"id":"D","text":"Basta comprobar dos trayectorias para probar existencia"}]'::jsonb, 'A', 'Coincidir en rectas no garantiza existencia (hay curvas como y=x² que pueden diferir). Pero una discrepancia sí prueba inexistencia.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-06', 4, 'Parábola crítica', 'dificil', 'Para f(x,y) = x²y/(x⁴+y²), el límite por la parábola y = x² (x≠0) vale:', '[{"id":"A","text":"0"},{"id":"B","text":"∞"},{"id":"C","text":"1"},{"id":"D","text":"1/2"}]'::jsonb, 'D', 'Sustituyendo: x²·x²/(x⁴+x⁴) = x⁴/2x⁴ = 1/2. Por los ejes vale 0: el límite no existe.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-07', 4, 'Síntesis polar', 'dificil', 'Si una trayectoria polar cumple r(θ) → 0 cuando θ → π, la nave:', '[{"id":"A","text":"Se aleja al infinito"},{"id":"B","text":"Describe un círculo de radio fijo"},{"id":"C","text":"Llega al polo (origen) en θ = π"},{"id":"D","text":"No puede interpretarse geométricamente"}]'::jsonb, 'C', 'r = 0 es el polo. Como en r = 2+2cos θ con θ=π, la trayectoria alcanza el origen.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-08', 4, 'Acotado por cero', 'dificil', 'lim((x,y)→(0,0)) (x³+y³)/(x²+y²) es igual a:', '[{"id":"A","text":"1"},{"id":"B","text":"0"},{"id":"C","text":"No existe"},{"id":"D","text":"∞"}]'::jsonb, 'B', 'En polares: r³(cos³θ+sin³θ)/r² = r·(acotado) → 0. Función acotada por cero.', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-09', 4, 'Error frecuente', 'media', 'Un estudiante aplica L''Hôpital a lim(x→0) (x+1)/x derivando como 1/1 = 1. El error es:', '[{"id":"A","text":"Aplicó la regla a una forma que no es 0/0 ni ∞/∞"},{"id":"B","text":"No hay error, el límite es 1"},{"id":"C","text":"Derivó mal: la derivada de x es 0"},{"id":"D","text":"Debió derivar dos veces"}]'::jsonb, 'A', 'Es forma 1/0, no indeterminada. El límite lateral es ±∞ (no existe como finito).', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-10', 4, 'Grado dominante', 'media', 'lim(x→−∞) (5x³−2x)/(x³+7) es igual a:', '[{"id":"A","text":"−∞"},{"id":"B","text":"−5"},{"id":"C","text":"0"},{"id":"D","text":"5"}]'::jsonb, 'D', 'Mismo grado: cociente de coeficientes líderes 5/1 = 5 (el signo de ∞ no cambia el cociente de grados iguales).', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
insert into public.questions (id, level, topic, difficulty, statement, options, correct_option_id, explanation, active) values ('n4-11', 4, 'Decisión final', 'dificil', 'Tres naves reportan: por y=0 el límite es 0, por x=0 es 0, por y=x² es 1/2. Conclusión correcta:', '[{"id":"A","text":"El límite es 0 por mayoría"},{"id":"B","text":"El límite es 1/4 (promedio)"},{"id":"C","text":"El límite no existe"},{"id":"D","text":"Falta información para decidir"}]'::jsonb, 'C', 'Basta una trayectoria con valor distinto para probar inexistencia. Es el caso clásico x²y/(x⁴+y²).', true) on conflict (id) do update set level=excluded.level, topic=excluded.topic, difficulty=excluded.difficulty, statement=excluded.statement, options=excluded.options, correct_option_id=excluded.correct_option_id, explanation=excluded.explanation, active=true;
